  const end = raw.lastIndexOf(CODEX_SYNC_MARKER);
  if (end >= 0) {
    const start = raw.lastIndexOf("\x1B[?2026h", end);
    if (start >= 0) {
      return cleanCodexTuiFrame(raw.slice(start, end + CODEX_SYNC_MARKER.length));
    }
  }
